expressionInfo.expression:
// ── 구리 등산로 시설물(지점) 팝업 (3D 씬용) ──
var 산명       = $feature.산명;
var 지점순번    = $feature.등산로지점순번;
var 관리지점명칭 = $feature.관리지점명칭;
var 상세지점명칭 = $feature.상세지점명칭;
var 기타사항    = $feature.기타사항;
var 과거지점번호 = $feature.과거지점번호;

function C(v) {
  if (IsEmpty(v)) { return '' }
  var s = Trim(Text(v));
  if (s == '-' || Lower(s) == 'null') { return '' }
  return s
}
function Row(icon, label, val) {
  if (C(val) == '') { return '' }
  return '<div style="display:flex;gap:8px;margin-bottom:7px;line-height:1.55">'
       + '<span style="min-width:88px;color:#5B6C66">' + icon + ' ' + label + '</span>'
       + '<span style="flex:1;color:#1A2B26">' + C(val) + '</span></div>'
}
function Chip(t, bg, fg) {
  return '<span style="display:inline-block;background:' + bg + ';color:' + fg
       + ';border-radius:12px;padding:3px 11px;font-size:12px;font-weight:700;'
       + 'margin:0 5px 5px 0">' + t + '</span>'
}

var html = '';

if (C(관리지점명칭) != '') {
  html += '<div style="margin-bottom:10px">' + Chip('📍 ' + C(관리지점명칭), '#E4F3EF', '#1F6E5C') + '</div>'
}

html += Row('🔢', '등산로 지점순번', 지점순번);
html += Row('🏷️', '지점 구분', 관리지점명칭);
html += Row('📌', '상세 지점', 상세지점명칭);
html += Row('ℹ️', '기타', 기타사항);

return { type: 'text', text: html }

// ── 구리 등산로 팝업 (3D 씬용) ──
var 산명       = $feature.산명;
var 등산로명    = $feature.등산로명;
var 순번       = $feature.등산로순번;
var 주요지점    = $feature.등산로주요지점내용;
var 길이       = $feature.등산로길이;
var 난이도     = $feature.등산로난이도명;
var 상행       = $feature.등산로상행시간;
var 하행       = $feature.등산로하행시간;
var 노면       = $feature.등산로재질내용;
var 통제여부    = $feature.등산로통제여부;
var 폐쇄여부    = $feature.등산로폐쇄여부;
var 위험구간    = $feature.등산로위험구간내용;
var 추천여부    = $feature.등산로추천여부;

function C(v) {
  if (IsEmpty(v)) { return '' }
  var s = Trim(Text(v));
  if (s == '-' || Lower(s) == 'null') { return '' }
  return s
}
function Yes(v) {
  var s = Lower(C(v));
  if (s == '') { return false }
  var no = '|n|no|x|없음|불가|해당없음|0|';
  if (Find('|' + s + '|', no) >= 0) { return false }
  return true
}
function Row(icon, label, val) {
  if (C(val) == '') { return '' }
  return '<div style="display:flex;gap:8px;margin-bottom:7px;line-height:1.55">'
       + '<span style="min-width:76px;color:#5B6C66">' + icon + ' ' + label + '</span>'
       + '<span style="flex:1;color:#1A2B26">' + C(val) + '</span></div>'
}
function Chip(t, bg, fg) {
  return '<span style="display:inline-block;background:' + bg + ';color:' + fg
       + ';border-radius:12px;padding:3px 11px;font-size:12px;font-weight:700;'
       + 'margin:0 5px 5px 0">' + t + '</span>'
}
function Mins(v) {
  if (IsEmpty(v)) { return '' }
  var n = Number(v);
  if (IsEmpty(n) || n <= 0) { return '' }
  return Text(n) + '분'
}

var html = '';

// ── 칩 (난이도 · 위험/통제/폐쇄 · 추천) ──
var chips = '';
if (C(난이도) != '') {
  var dc = Decode(난이도,
    '쉬움',   '#E4F7EF|#0F6E56',
    '보통',   '#FFF4E0|#B26A00',
    '어려움', '#FDECEA|#B3261E', '#EDEFEE|#3F4E48');
  var dp = Split(dc, '|');
  chips += Chip('⛰️ 등산난이도 ' + C(난이도), dp[0], dp[1])
}
if (C(위험구간) != '') { chips += Chip('⚠️ 위험구간 있음', '#FDECEA', '#B3261E') }
if (Yes(통제여부))     { chips += Chip('🚧 통제 중', '#FDECEA', '#B3261E') }
if (Yes(폐쇄여부))     { chips += Chip('⛔ 폐쇄', '#FDECEA', '#B3261E') }
if (Yes(추천여부))     { chips += Chip('👍 추천 코스', '#E4F7EF', '#0F6E56') }
if (chips != '') { html += '<div style="margin-bottom:10px">' + chips + '</div>' }

// ── 길이 (값이 작으면 km, 크면 m 로 표기) ──
var lenTxt = '';
if (!IsEmpty(길이)) {
  var ln = Number(길이);
  if (!IsEmpty(ln) && ln > 0) {
    lenTxt = IIf(ln < 100, Text(Round(ln, 2)) + 'km', Text(Round(ln)) + 'm')
  }
}

// ── 정보 행 ──
html += Row('🔢', '등산로순번', 순번);
html += Row('📏', '등산로 길이', lenTxt);
html += Row('⬆️', '상행시간', Mins(상행));
html += Row('⬇️', '하행시간', Mins(하행));
html += Row('🧭', '주요지점', 주요지점);
html += Row('🪨', '노면', 노면);
html += Row('⚠️', '위험구간', 위험구간);

html += '<div style="margin-top:10px;font-size:11.5px;color:#8A968F">'
     + '산에서 사고가 나면 이 등산로 이름과 순번을 119에 알려주세요</div>';

return { type: 'text', text: html }

// ── 구리 둘레길 시설물 팝업 (3D 씬용) — 네이버 길찾기 없음 ──
var 둘레길이름  = $feature.둘레길이름;
var 관심지점정보 = $feature.관심지점정보;
var 상세정보    = $feature.상세정보;
var 기타사항    = $feature.기타사항;

function C(v) {
  if (IsEmpty(v)) { return '' }
  var s = Trim(Text(v));
  if (s == '-' || Lower(s) == 'null') { return '' }
  return s
}
function Row(icon, label, val) {
  if (C(val) == '') { return '' }
  return '<div style="display:flex;gap:8px;margin-bottom:7px;line-height:1.55">'
       + '<span style="min-width:76px;color:#5B6C66">' + icon + ' ' + label + '</span>'
       + '<span style="flex:1;color:#1A2B26">' + C(val) + '</span></div>'
}
function Chip(t, bg, fg) {
  return '<span style="display:inline-block;background:' + bg + ';color:' + fg
       + ';border-radius:12px;padding:3px 11px;font-size:12px;font-weight:700;'
       + 'margin:0 5px 5px 0">' + t + '</span>'
}

var html = '';

if (C(둘레길이름) != '') {
  html += '<div style="margin-bottom:10px">' + Chip(C(둘레길이름), '#E4F3EF', '#1F6E5C') + '</div>'
}

html += Row('🚩', '둘레길', 둘레길이름);
html += Row('📍', '상세', 상세정보);
html += Row('ℹ️', '기타', 기타사항);

return { type: 'text', text: html }

// ── 구리 둘레길 팝업 (3D 씬용) ──
var 코스     = $feature.코스;
var 길이름   = $feature.길이름;
var 구간길이 = $feature.구간길이;
var 시간     = $feature.시간;
var 코스설명 = $feature.코스설명;

var ACCENT = '#2E7D6B';   // 둘레길 강조색(초록)

function C(v) {
  if (IsEmpty(v)) { return '' }
  var s = Trim(Text(v));
  if (s == '-' || Lower(s) == 'null') { return '' }
  return s
}
function Row(icon, label, val) {
  if (C(val) == '') { return '' }
  return '<div style="display:flex;gap:8px;margin-bottom:7px;line-height:1.55">'
       + '<span style="min-width:76px;color:#5B6C66">' + icon + ' ' + label + '</span>'
       + '<span style="flex:1;color:#1A2B26">' + C(val) + '</span></div>'
}
function Chip(t, bg, fg) {
  return '<span style="display:inline-block;background:' + bg + ';color:' + fg
       + ';border-radius:12px;padding:3px 11px;font-size:12px;font-weight:700;'
       + 'margin:0 5px 5px 0">' + t + '</span>'
}

var html = '';

// ── 칩 (코스) ──
if (C(코스) != '') {
  html += '<div style="margin-bottom:10px">' + Chip('둘레길 ' + C(코스), '#E4F3EF', '#1F6E5C') + '</div>'
}

// ── 코스 소개(구리 문화관광 안내 기준, 확인된 코스만) ──
var s = C(코스);
var cn = '';
for (var i = 0; i < Count(s); i++) {
  var ch = Mid(s, i, 1);
  if (ch >= '0' && ch <= '9') { cn = ch; break }
}
var sub = Decode(cn,
  '1', '역사와 자연이 살아있는 둘레길',
  '2', '구릉산과 갈매마을을 잇는 둘레길',
  '3', '왕숙천과 도심생활공원이 조화로운 둘레길',
  '4', '구리한강시민공원이 있는 둘레길', '');
if (sub != '') {
  html += '<div style="background:#EEF6F3;border-radius:10px;padding:10px 12px;'
        + 'margin-bottom:10px;color:#1F5A4C;line-height:1.6">💡 ' + sub + '</div>'
}

// ── 정보 행 ──
html += Row('📏', '길이', 구간길이);
html += Row('🕐', '소요시간', 시간);
html += Row('🧭', '코스설명', 코스설명);

html += '<div style="margin-top:10px;font-size:11.5px;color:#8A968F">'
     + '코스 정보는 구리 문화관광 안내 기준이라 현장과 다를 수 있어요</div>';

return { type: 'text', text: html }

// ── 구리 3D 건물 LOD2 팝업 (씬용) ──
var 건물명칭  = $feature.buld_nm;    // 건물명칭
var 부명칭    = $feature.batc_nm;    // 건물부명칭
var 층수     = $feature.bflr_co;    // 건물층수
var 본번     = $feature.bldmn_no;   // 건물번호 본번
var 부번     = $feature.bldsl_no;   // 건물번호 부번
var 기본높이  = $feature.bldh_bv;    // 건물 기본높이
var pnu      = $feature.pnu_no;     // PNU 번호

function C(v) {
  if (IsEmpty(v)) { return '' }
  var s = Trim(Text(v));
  if (s == '-' || Lower(s) == 'null') { return '' }
  return s
}
function Pos(v) {
  if (IsEmpty(v)) { return -1 }
  var n = Number(v);
  if (IsEmpty(n)) { return -1 }
  return n
}
// 코드값을 이름으로 (도메인 있으면 이름, 없으면 코드 그대로)
function DName(fld) {
  var d = C(DomainName($feature, fld));
  if (d != '') { return d }
  return C($feature[fld])
}
function Row(icon, label, val) {
  if (C(val) == '') { return '' }
  return '<div style="display:flex;gap:8px;margin-bottom:7px;line-height:1.55">'
       + '<span style="min-width:84px;color:#5B6C66">' + icon + ' ' + label + '</span>'
       + '<span style="flex:1;color:#1A2B26">' + C(val) + '</span></div>'
}
function Chip(t, bg, fg) {
  return '<span style="display:inline-block;background:' + bg + ';color:' + fg
       + ';border-radius:12px;padding:3px 11px;font-size:12px;font-weight:700;'
       + 'margin:0 5px 5px 0">' + t + '</span>'
}
function Mtr(v) { var n = Pos(v); if (n <= 0) { return '' } return Text(n, '#,##0.#') + 'm' }

var 용도 = DName('bprp_se');   // 건물용도구분 (예: 자동차관련시설)
var 건물구분 = DName('buld_se'); // 건물구분 (예: 무벽건물)

var html = '';

// ── 칩 (용도 · 건물구분) — 코드가 아니라 이름으로 ──
var chips = '';
if (용도 != '')     { chips += Chip('🏢 ' + 용도, '#E8F0FD', '#2A57A8') }
if (건물구분 != '') { chips += Chip(건물구분, '#EEF0F2', '#3F4E5A') }
if (chips != '') { html += '<div style="margin-bottom:10px">' + chips + '</div>' }

// ── 건물명칭 (부명칭을 제목으로 쓰므로, 명칭이 따로 있으면 부제로) ──
if (C(건물명칭) != '' && C(건물명칭) != C(부명칭)) {
  html += '<div style="margin-bottom:10px;color:#5B6C66;font-size:13px">' + C(건물명칭) + '</div>'
}

// ── 건물번호 (본번-부번) ──
var bno = '';
if (Pos(본번) > 0) {
  bno = Text(Pos(본번));
  if (Pos(부번) > 0) { bno = bno + '-' + Text(Pos(부번)) }
}

// ── 정보 행 ──
html += Row('🏙️', '건물층수', IIf(Pos(층수) > 0, Text(Pos(층수)) + '층', ''));
html += Row('📏', '기본높이', Mtr(기본높이));
html += Row('🔖', '건물번호', bno);
html += Row('🧾', 'PNU 번호', pnu);

html += '<div style="margin-top:10px;font-size:11.5px;color:#8A968F">'
     + '국토지리정보원 3D 건물(LOD2) 기준 정보예요</div>';

return { type: 'text', text: html }

// ── 구리 3D 건물 팝업 (씬용) — 3D_Buildings_LOD1_2508 ──
var pnu      = $feature.pnu;            // 필지고유번호
var 용도     = $feature.main_usg_nm;    // 주요용도명
var 기타용도  = $feature.etc_usg_nm;     // 기타용도명
var 구조     = $feature.bdst_strc_nm;   // 건축물구조명
var 지붕     = $feature.roof_nm;        // 지붕명
var 상세건물명 = $feature.dtl_bldg_nm;   // 상세건물명
var 지상     = $feature.grnd_nofl;      // 지상층수
var 지하     = $feature.udgd_nofl;      // 지하층수
var 층수     = $feature.bldg_nofl;      // 건물층수
var 높이     = $feature.bldg_hgt;       // 건물높이
var 대지     = $feature.siar;           // 대지면적
var 건축     = $feature.bdar;           // 건축면적
var 연면적    = $feature.tfar;           // 연면적
var 건폐율    = $feature.bdcvrt;         // 건폐율
var 용적률    = $feature.fart;           // 용적률
var 세대     = $feature.hh_cnt;         // 세대수
var 가구     = $feature.hshd_cnt;       // 가구수
var 승인일    = $feature.use_aprv_ymd;   // 사용승인일자
var 행정구역  = $feature.adm_nm;         // 행정구역명
var 본번     = $feature.bmno;           // 건물본번
var 부번     = $feature.bsno;           // 건물부번

function C(v) {
  if (IsEmpty(v)) { return '' }
  var s = Trim(Text(v));
  if (s == '-' || Lower(s) == 'null') { return '' }
  return s
}
function Pos(v) {
  if (IsEmpty(v)) { return -1 }
  var n = Number(v);
  if (IsEmpty(n)) { return -1 }
  return n
}
function Row(icon, label, val) {
  if (C(val) == '') { return '' }
  return '<div style="display:flex;gap:8px;margin-bottom:7px;line-height:1.55">'
       + '<span style="min-width:84px;color:#5B6C66">' + icon + ' ' + label + '</span>'
       + '<span style="flex:1;color:#1A2B26">' + C(val) + '</span></div>'
}
function Chip(t, bg, fg) {
  return '<span style="display:inline-block;background:' + bg + ';color:' + fg
       + ';border-radius:12px;padding:3px 11px;font-size:12px;font-weight:700;'
       + 'margin:0 5px 5px 0">' + t + '</span>'
}
function Area(v) { var n = Pos(v); if (n <= 0) { return '' } return Text(n, '#,##0.#') + ' ㎡' }
function Pct(v)  { var n = Pos(v); if (n <= 0) { return '' } return Text(n, '#,##0.#') + '%' }
function Mtr(v)  { var n = Pos(v); if (n <= 0) { return '' } return Text(n, '#,##0.#') + 'm' }
function Ymd(v)  { var s = C(v); if (Count(s) < 8) { return s } return Left(s, 4) + '.' + Mid(s, 4, 2) + '.' + Mid(s, 6, 2) }

var html = '';

// ── 칩 (용도 · 구조) ──
var chips = '';
if (C(용도) != '')    { chips += Chip('🏢 ' + C(용도), '#E8F0FD', '#2A57A8') }
if (C(기타용도) != '' && C(기타용도) != C(용도)) { chips += Chip(C(기타용도), '#EEF2FB', '#3A5A93') }
if (C(구조) != '')    { chips += Chip('🧱 ' + C(구조), '#EEF0F2', '#3F4E5A') }
if (chips != '') { html += '<div style="margin-bottom:10px">' + chips + '</div>' }

if (C(상세건물명) != '') {
  html += '<div style="margin-bottom:10px;color:#5B6C66;font-size:13px">' + C(상세건물명) + '</div>'
}

// ── 층수 (지상/지하 묶기) ──
var fl = '';
if (Pos(지상) > 0) { fl = '지상 ' + Text(Pos(지상)) + '층' }
if (Pos(지하) > 0) { fl = fl + IIf(fl != '', ' · ', '') + '지하 ' + Text(Pos(지하)) + '층' }
if (fl == '' && Pos(층수) > 0) { fl = Text(Pos(층수)) + '층' }

// ── 세대/가구 (0이면 숨김) ──
var hh = '';
if (Pos(세대) > 0) { hh = Text(Pos(세대)) + '세대' }
if (Pos(가구) > 0) { hh = hh + IIf(hh != '', ' · ', '') + Text(Pos(가구)) + '가구' }

// ── 건물번호 (본번-부번) ──
var bno = '';
if (Pos(본번) > 0) {
  bno = Text(Pos(본번));
  if (Pos(부번) > 0) { bno = bno + '-' + Text(Pos(부번)) }
}

// ── 정보 행 ──
html += Row('🏙️', '층수', fl);
html += Row('📏', '높이', Mtr(높이));
html += Row('📐', '대지면적', Area(대지));
html += Row('🏗️', '건축면적', Area(건축));
html += Row('📊', '연면적', Area(연면적));
