       + 'margin:0 5px 5px 0">' + t + '</span>'
}
function AmChip(t) {
  return '<span style="display:inline-block;background:#F0F3F1;color:#3F4E48;'
       + 'border-radius:10px;padding:3px 10px;font-size:12px;margin:0 5px 5px 0">' + t + '</span>'
