  var t = Replace(Replace(Trim(Text(raw)), ';', '\n'), ',', '\n');
  var parts = Split(t, '\n');
  var gal = '';
  var n = 0;
  for (var i in parts) {
    var u = Trim(parts[i]);
    if (u != '' && Find('http', u) == 0 && n < 5) {
      if (Find('https://', u) != 0) { u = Replace(u, 'http://', 'https://') }
      gal += '<img src="' + u + '" style="height:150px;border-radius:10px;margin-right:6px">';
      n++;
