}

// ── 편의시설 아케이드 (있는 것만) ──
var am = '';
if (Yes(주차장))     { am += AmChip('🅿️ 주차') }
if (Yes(화장실))     { am += AmChip('🚻 화장실') }
if (Yes(수유실))     { am += AmChip('🍼 수유실') }
if (Yes(유모차대여)) { am += AmChip('👶 유모차대여') }
