}

// ── 버튼 (전화만, 네이버 길찾기 없음) ──
if (C(문의처) != '') {
  html += '<div style="margin-top:12px">'
       + '<a href="tel:' + C(문의처) + '" '
       + 'style="display:block;text-align:center;background:' + ACCENT + ';color:#fff;'
