          + '</div>'
  } else if (n > 1) {
    html += '<div style="white-space:nowrap;overflow-x:auto;margin-bottom:10px">' + gal + '</div>'
  }
}

var chips = '';
if (C(시작일) != '') {
  var s = Date(C(시작일));
  var e = IIf(C(종료일) != '', Date(C(종료일)), s);
  if (!IsEmpty(s)) {
    var today = Today();
    if (today < s) {
      chips += Chip('🗓️ ' + Text(Floor(DateDiff(s, today, 'days'))) + '일 남음', '#FFF4E0', '#B26A00')
    } else if (today <= DateAdd(e, 1, 'days')) {
      chips += Chip('🎪 지금 열리는 중', '#E4F7EF', '#0F6E56')
    } else {
      chips += Chip('올해 행사는 끝났어요', '#F1F1F1', '#5B6472')
    }
  }
}
