}
if (C(요금) != '')     { chips += Chip('💰 ' + C(요금), '#E4F7EF', '#0F6E56') }
if (chips != '') { html += '<div style="margin-bottom:10px">' + chips + '</div>' }

if (Brief(축제소개, 120) != '') {
  html += '<div style="background:#FDF4F7;border-radius:10px;padding:10px 12px;'
