}

var term = C(시작일);
if (C(시작일) != '' && C(종료일) != '' && C(시작일) != C(종료일)) {
  term = C(시작일) + ' ~ ' + C(종료일)
}
var tm = '';
if (C(시작시간) != '') {
  tm = C(시작시간) + IIf(C(종료시간) != '', ' ~ ' + C(종료시간), '')
}
var place = C(장소명);
if (place != '' && C(행정동) != '') { place = place + ' (' + C(행정동) + ')' }
var host = C(주최);
if (C(주관) != '' && C(주관) != C(주최)) { host = Trim(host + ' · ' + C(주관)) }

html += Row('📅', '기간', term);
html += Row('🕐', '시간', tm);
html += Row('📍', '장소', place);
html += Row('🗺️', '주소', 주소);
html += Row('🏛️', '주최·주관', host);
html += Row('🎬', '주요프로그램', Brief(주요프로그램, 140));
html += Row('🔗', '연계행사', 연계행사);
html += Row('📞', '문의처', 문의처);
html += Row('ℹ️', '참고', Brief(NoteClean(비고), 100));

if (LinkOK(공식페이지)) {
  html += '<div style="margin-top:12px">'
       + '<a href="' + C(공식페이지) + '" target="_blank" '
